import{Code}from"../code.js";export function codeFromHttpStatus(httpStatus){switch(httpStatus){case 400:return Code.InvalidArgument;case 401:return Code.Unauthenticated;case 403:return Code.PermissionDenied;case 404:return Code.Unimplemented;case 408:return Code.DeadlineExceeded;case 409:return Code.Aborted;case 412:return Code.FailedPrecondition;case 413:case 431:return Code.ResourceExhausted;case 415:return Code.Internal;case 429:case 502:case 503:case 504:return Code.Unavailable;default:return Code.Unknown}}export function codeToHttpStatus(code){switch(code){case Code.Canceled:return 408;case Code.Unknown:return 500;case Code.InvalidArgument:return 400;case Code.DeadlineExceeded:return 408;case Code.NotFound:return 404;case Code.AlreadyExists:return 409;case Code.PermissionDenied:return 403;case Code.ResourceExhausted:return 429;case Code.FailedPrecondition:return 412;case Code.Aborted:return 409;case Code.OutOfRange:return 400;case Code.Unimplemented:return 404;case Code.Internal:return 500;case Code.Unavailable:return 503;case Code.DataLoss:return 500;case Code.Unauthenticated:return 401;default:return 500}}