import{verifyTypedData as viem_verifyTypedData}from"viem/actions";import{getAction}from"../utils/getAction.js";export async function verifyTypedData(config,parameters){const{chainId:chainId,...rest}=parameters,client=config.getClient({chainId:chainId});return getAction(client,viem_verifyTypedData,"verifyTypedData")(rest)}