import{infiniteReadContractsQueryOptions,structuralSharing}from"@wagmi/core/query";import{useInfiniteQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useInfiniteReadContracts(parameters){const{contracts:contracts=[],query:query}=parameters,config=useConfig(parameters),chainId=useChainId({config:config}),options=infiniteReadContractsQueryOptions(config,{...parameters,chainId:chainId,contracts:contracts,query:query});return useInfiniteQuery({...query,...options,initialPageParam:options.initialPageParam,structuralSharing:query.structuralSharing??structuralSharing})}