import{createClient,custom}from"viem";import{getAddress,parseAccount}from"viem/utils";import{ConnectorAccountNotFoundError,ConnectorChainMismatchError,ConnectorNotConnectedError,ConnectorUnavailableReconnectingError}from"../errors/config.js";export async function getConnectorClient(config,parameters={}){let connection;if(parameters.connector){const{connector:connector}=parameters;if("reconnecting"===config.state.status&&!connector.getAccounts&&!connector.getChainId)throw new ConnectorUnavailableReconnectingError({connector:connector});const[accounts,chainId]=await Promise.all([connector.getAccounts().catch((e=>{if(null===parameters.account)return[];throw e})),connector.getChainId()]);connection={accounts:accounts,chainId:chainId,connector:connector}}else connection=config.state.connections.get(config.state.current);if(!connection)throw new ConnectorNotConnectedError;const chainId=parameters.chainId??connection.chainId,connectorChainId=await connection.connector.getChainId();if(connectorChainId!==connection.chainId)throw new ConnectorChainMismatchError({connectionChainId:connection.chainId,connectorChainId:connectorChainId});const connector=connection.connector;if(connector.getClient)return connector.getClient({chainId:chainId});const account=parseAccount(parameters.account??connection.accounts[0]);if(account&&(account.address=getAddress(account.address)),parameters.account&&!connection.accounts.some((x=>x.toLowerCase()===account.address.toLowerCase())))throw new ConnectorAccountNotFoundError({address:account.address,connector:connector});const chain=config.chains.find((chain=>chain.id===chainId)),provider=await connection.connector.getProvider({chainId:chainId});return createClient({account:account,chain:chain,name:"Connector Client",transport:opts=>custom(provider)({...opts,retryCount:0})})}