import{getCapabilitiesQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useAccount}from"./useAccount.js";import{useConfig}from"./useConfig.js";export function useCapabilities(parameters={}){const{account:account,query:query={}}=parameters,{address:address}=useAccount(),config=useConfig(parameters),options=getCapabilitiesQueryOptions(config,{...parameters,account:account??address});return useQuery({...query,...options})}