import{ContractFunctionExecutionError,formatUnits,hexToString,trim}from"viem";import{getUnit}from"../utils/getUnit.js";import{readContracts}from"./readContracts.js";export async function getToken(config,parameters){const{address:address,chainId:chainId,formatUnits:unit=18}=parameters;function getAbi(type){return[{type:"function",name:"decimals",stateMutability:"view",inputs:[],outputs:[{type:"uint8"}]},{type:"function",name:"name",stateMutability:"view",inputs:[],outputs:[{type:type}]},{type:"function",name:"symbol",stateMutability:"view",inputs:[],outputs:[{type:type}]},{type:"function",name:"totalSupply",stateMutability:"view",inputs:[],outputs:[{type:"uint256"}]}]}try{const contractConfig={address:address,abi:getAbi("string"),chainId:chainId},[decimals,name,symbol,totalSupply]=await readContracts(config,{allowFailure:!0,contracts:[{...contractConfig,functionName:"decimals"},{...contractConfig,functionName:"name"},{...contractConfig,functionName:"symbol"},{...contractConfig,functionName:"totalSupply"}]});if(name.error instanceof ContractFunctionExecutionError)throw name.error;if(symbol.error instanceof ContractFunctionExecutionError)throw symbol.error;if(decimals.error)throw decimals.error;if(totalSupply.error)throw totalSupply.error;return{address:address,decimals:decimals.result,name:name.result,symbol:symbol.result,totalSupply:{formatted:formatUnits(totalSupply.result,getUnit(unit)),value:totalSupply.result}}}catch(error){if(error instanceof ContractFunctionExecutionError){const contractConfig={address:address,abi:getAbi("bytes32"),chainId:chainId},[decimals,name,symbol,totalSupply]=await readContracts(config,{allowFailure:!1,contracts:[{...contractConfig,functionName:"decimals"},{...contractConfig,functionName:"name"},{...contractConfig,functionName:"symbol"},{...contractConfig,functionName:"totalSupply"}]});return{address:address,decimals:decimals,name:hexToString(trim(name,{dir:"right"})),symbol:hexToString(trim(symbol,{dir:"right"})),totalSupply:{formatted:formatUnits(totalSupply,getUnit(unit)),value:totalSupply}}}throw error}}