import{useCallback,useContext}from"react";import{ACTIONS}from"../state/constants";import{PortalDispatchContext}from"../contexts/portal";export const usePortal=(hostName="root")=>{const dispatch=useContext(PortalDispatchContext);if(null===dispatch)throw new Error("'PortalDispatchContext' cannot be null, please add 'PortalProvider' to the root component.");const registerHost=useCallback((()=>{dispatch({type:ACTIONS.REGISTER_HOST,hostName:hostName})}),[]),deregisterHost=useCallback((()=>{dispatch({type:ACTIONS.DEREGISTER_HOST,hostName:hostName})}),[]),addUpdatePortal=useCallback(((name,node)=>{dispatch({type:ACTIONS.ADD_UPDATE_PORTAL,hostName:hostName,portalName:name,node:node})}),[]);return{registerHost:registerHost,deregisterHost:deregisterHost,addPortal:addUpdatePortal,updatePortal:addUpdatePortal,removePortal:useCallback((name=>{dispatch({type:ACTIONS.REMOVE_PORTAL,hostName:hostName,portalName:name})}),[])}};