import{addEventListeners,timeStampNow}from"@datadog/browser-core";import{RecordType}from"../../../types";export function trackFocus(configuration,focusCb){return addEventListeners(configuration,window,["focus","blur"],(function(){focusCb({data:{has_focus:document.hasFocus()},type:RecordType.Focus,timestamp:timeStampNow()})}))}