export function startInternalContext(applicationId,sessionManager,viewContexts,actionContexts,urlContexts){return{get:function(startTime){var viewContext=viewContexts.findView(startTime),urlContext=urlContexts.findUrl(startTime),session=sessionManager.findTrackedSession(startTime);if(session&&viewContext&&urlContext){var actionId=actionContexts.findActionId(startTime);return{application_id:applicationId,session_id:session.id,user_action:actionId?{id:actionId}:void 0,view:{id:viewContext.id,name:viewContext.name,referrer:urlContext.referrer,url:urlContext.url}}}}}}